"use strict";(()=>{const status=document.getElementById('postStatus');let timer;document.querySelectorAll('[data-route]').forEach((button)=>button.addEventListener('click',()=>{if(parent!==window){parent.postMessage({namespace:'ctuav-demo',type:'route',route:button.dataset.route},'*');return;}
status.textContent='This link opens a page in the combined demo';status.hidden=false;clearTimeout(timer);timer=setTimeout(()=>{status.hidden=true;},3600);}));})();addEventListener('message',event=>{if(event.source!==parent||event.data?.namespace!=='ctuav-demo'||event.data.type!=='palette')return;const theme=event.data.theme;document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;document.querySelectorAll('.palette-button').forEach(button=>{button.classList.toggle('selected',button.dataset.palette===theme);button.setAttribute('aria-pressed',String(button.dataset.palette===theme));});});addEventListener('message',event=>{if(event.source===parent&&event.data?.namespace==='ctuav-demo'&&event.data.type==='view-active'&&event.data.active)scrollTo({top:0,behavior:'instant'});});"use strict";(()=>{document.querySelectorAll('[data-footer-route]').forEach((button)=>button.addEventListener('click',()=>{const route=button.dataset.footerRoute;if(window.ctuavDemo)window.ctuavDemo.navigate(route);else if(parent!==window)parent.postMessage({namespace:'ctuav-demo',type:'route',route},'*');}));})();